const fs=require('fs'),path=require('path'),crypto=require('crypto');
const updates=[{"file":"src/App.tsx","before":"3ce5098816443e273999e9553a533cd6d969bedc3f5eabc9236d0da1f2feb8d4","next":"import { useEffect } from 'react';\nimport { CartProvider } from '@/context/CartContext';\nimport { PrescriptionBasketProvider } from '@/context/PrescriptionBasketContext';\nimport { MemberProvider } from '@/context/MemberContext';\nimport { CustomerAuthProvider } from '@/context/CustomerAuthContext';\nimport { useRouter } from '@/router';\nimport { Header } from '@/components/Header';\nimport { Footer } from '@/components/Footer';\nimport { CartDrawer } from '@/components/CartDrawer';\nimport { PrescriptionBasketDrawer } from '@/components/PrescriptionBasketDrawer';\nimport { HomePage } from '@/pages/HomePage';\nimport { GoalsPage } from '@/pages/GoalsPage';\nimport { GoalPage } from '@/pages/GoalPage';\nimport { SectionPage } from '@/pages/SectionPage';\nimport { BestSellersPage } from '@/pages/BestSellersPage';\nimport { ProductPage } from '@/pages/ProductPage';\nimport { CheckoutPage } from '@/pages/CheckoutPage';\nimport { GrouponPage } from '@/pages/GrouponPage';\nimport { OrderPaymentInstructionsPage } from '@/pages/OrderPaymentInstructionsPage';\nimport { KashuCardResultPage } from '@/pages/KashuCardResultPage';\nimport { SuccessPage } from '@/pages/SuccessPage';\nimport { CancelPage } from '@/pages/CancelPage';\nimport { TrackPage } from '@/pages/TrackPage';\nimport { AboutPage } from '@/pages/AboutPage';\nimport { FaqPage } from '@/pages/FaqPage';\nimport { SubscriptionsPage } from '@/pages/SubscriptionsPage';\nimport { AlaCartePage } from '@/pages/AlaCartePage';\nimport { RefundPolicyPage } from '@/pages/RefundPolicyPage';\nimport { ContactPage } from '@/pages/ContactPage';\nimport { ShopAllPage } from '@/pages/ShopAllPage';\nimport { PrivacyPolicyPage } from '@/pages/PrivacyPolicyPage';\nimport { TermsPage } from '@/pages/TermsPage';\nimport { SmsRemindersPage } from '@/pages/SmsRemindersPage';\nimport { ConcernPage } from '@/pages/ConcernPage';\nimport { ShippingPolicyPage } from '@/pages/ShippingPolicyPage';\nimport { BUILD_VERSION } from '@/buildVersion';\n\n// Keep the deploy marker in the customer bundle for staging sync verification (not rendered).\n(globalThis as typeof globalThis & { __MBM_BUILD_VERSION__?: string }).__MBM_BUILD_VERSION__ =\n  BUILD_VERSION;\nimport { AccessibilityPage } from '@/pages/AccessibilityPage';\nimport { ConsumerDataPage } from '@/pages/ConsumerDataPage';\nimport { SubscriptionTermsPage } from '@/pages/SubscriptionTermsPage';\nimport { MedicalDirectorPage } from '@/pages/MedicalDirectorPage';\nimport { LabDetailPage, OrderLabsPage } from '@/pages/OrderLabsPage';\nimport { AdminApp } from '@/admin/AdminApp';\nimport { AccountGate } from '@/pages/account/AccountGate';\nimport { AccountLoginPage } from '@/pages/account/AccountLoginPage';\nimport { AccountSignupPage } from '@/pages/account/AccountSignupPage';\nimport { AccountAuthCallbackPage } from '@/pages/account/AccountAuthCallbackPage';\nimport { AccountResetPasswordPage } from '@/pages/account/AccountResetPasswordPage';\nimport { AccountOverviewPage } from '@/pages/account/AccountOverviewPage';\nimport { AccountProfilePage } from '@/pages/account/AccountProfilePage';\nimport { AccountComingSoonPage } from '@/pages/account/AccountComingSoonPage';\nimport { AccountOrdersPage } from '@/pages/account/AccountOrdersPage';\nimport { AccountOrderDetailPage } from '@/pages/account/AccountOrderDetailPage';\nimport { CherryFinancingWidget } from '@/components/CherryFinancingWidget';\nimport { WelcomePopup } from '@/components/WelcomePopup';\nimport { FeelingPopup } from '@/components/FeelingPopup';\nimport { CareCheckoutReturn } from '@/components/CareCheckoutReturn';\nimport { CareSaveProgress } from '@/components/CareSaveProgress';\n\nfunction App() {\n  const route = useRouter();\n  const { path } = route;\n\n  // Redirect legacy hash URLs to clean path URLs on initial load\n  useEffect(() => {\n    if (window.location.hash && window.location.hash.startsWith('#/')) {\n      const cleanPath = window.location.hash.slice(1);\n      window.history.replaceState({}, '', cleanPath);\n      window.dispatchEvent(new PopStateEvent('popstate'));\n    }\n  }, []);\n\n  // Legacy /shop alias → canonical /shop-all\n  useEffect(() => {\n    if (path === '/shop') {\n      window.history.replaceState({}, '', '/shop-all');\n      window.dispatchEvent(new PopStateEvent('popstate'));\n    }\n  }, [path]);\n\n  // Admin area renders with its own chrome (no storefront header/footer/cart).\n  if (path === '/admin' || path.startsWith('/admin/')) {\n    return <AdminApp route={route} />;\n  }\n\n  const renderPage = () => {\n    if (path === '/' || path === '') return <HomePage />;\n    if (path === '/goals') return <GoalsPage />;\n    if (path.startsWith('/goal/')) return <GoalPage goalId={path.replace('/goal/', '')} />;\n    if (path.startsWith('/concern/')) return <ConcernPage concernId={path.replace('/concern/', '')} />;\n    if (path.startsWith('/section/')) return <SectionPage sectionId={path.replace('/section/', '')} subFilter={route.query.sub} />;\n    if (path === '/best-sellers') return <BestSellersPage />;\n    if (path.startsWith('/product/')) return <ProductPage slug={path.replace('/product/', '')} />;\n    if (path === '/checkout') return <CheckoutPage />;\n    if (path === '/groupon') return <GrouponPage />;\n    if (path.startsWith('/order/payment/')) {\n      const orderNumber = path.replace('/order/payment/', '').split('/')[0];\n      return <OrderPaymentInstructionsPage publicOrderNumber={orderNumber} />;\n    }\n    if (path.startsWith('/order/card-result/')) {\n      return <KashuCardResultPage />;\n    }\n    if (path === '/success') return <SuccessPage />;\n    if (path === '/cancel') return <CancelPage />;\n\n    if (path === '/account/login') {\n      return (\n        <AccountGate publicOnly>\n          <AccountLoginPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/signup') {\n      return (\n        <AccountGate publicOnly>\n          <AccountSignupPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/auth/callback') {\n      return (\n        <AccountGate publicOnly>\n          <AccountAuthCallbackPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/reset-password') {\n      return (\n        <AccountGate publicOnly>\n          <AccountResetPasswordPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account') {\n      return (\n        <AccountGate>\n          <AccountOverviewPage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/profile') {\n      return (\n        <AccountGate>\n          <AccountProfilePage />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/orders') {\n      return (\n        <AccountGate>\n          <AccountOrdersPage />\n        </AccountGate>\n      );\n    }\n    if (path.startsWith('/account/orders/')) {\n      const orderId = path.replace('/account/orders/', '').split('/')[0];\n      return (\n        <AccountGate>\n          <AccountOrderDetailPage orderId={orderId} />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/subscriptions' || path === '/account/membership' || path === '/account/auto-refill') {\n      return (\n        <AccountGate>\n          <AccountComingSoonPage\n            active=\"membership\"\n            title=\"Subscriptions\"\n            description=\"Prescription renewals and subscription-related care steps are handled securely in GEN Health.\"\n          />\n        </AccountGate>\n      );\n    }\n    if (path === '/account/requests') {\n      return (\n        <AccountGate>\n          <AccountComingSoonPage\n            active=\"requests\"\n            title=\"Requests\"\n            description=\"Prescription requests, refill questions, follow-ups, and lab review steps continue in GEN Health.\"\n          />\n        </AccountGate>\n      );\n    }\n\n    if (path === '/track') return <TrackPage />;\n    if (path === '/about') return <AboutPage />;\n    if (path === '/medical-director') return <MedicalDirectorPage />;\n    if (path.startsWith('/order-labs/')) return <LabDetailPage slug={path.replace('/order-labs/', '').split('/')[0]} />;\n    if (path === '/order-labs') return <OrderLabsPage />;\n    if (path === '/faq') return <FaqPage />;\n    if (path === '/memberships' || path === '/subscriptions') return <SubscriptionsPage />;\n    if (path === '/alacarte') return <AlaCartePage />;\n    if (path === '/refund-policy') return <RefundPolicyPage />;\n    if (path === '/shipping-policy') return <ShippingPolicyPage />;\n    if (path === '/membership-terms' || path === '/subscription-terms') return <SubscriptionTermsPage />;\n    if (path === '/accessibility') return <AccessibilityPage />;\n    if (path === '/consumer-data') return <ConsumerDataPage />;\n    if (path === '/contact') return <ContactPage />;\n    if (path === '/shop' || path === '/shop-all') return <ShopAllPage />;\n    if (path === '/privacy-policy') return <PrivacyPolicyPage />;\n    if (path === '/terms') return <TermsPage />;\n    if (path === '/sms-reminders') return <SmsRemindersPage />;\n\n    return (\n      <div className=\"pt-32 pb-20 text-center\">\n        <p className=\"font-serif text-3xl text-ink-900 mb-3\">Page not found</p>\n        <p className=\"text-ink-500 mb-6\">The page you are looking for does not exist.</p>\n        <a href=\"/\" className=\"btn-primary\">Back to Home</a>\n      </div>\n    );\n  };\n\n  return (\n    <CustomerAuthProvider>\n      <MemberProvider>\n        <PrescriptionBasketProvider>\n          <CartProvider>\n            <div className=\"min-h-screen bg-cream-50\">\n              <Header />\n              <main>{renderPage()}</main>\n              <Footer />\n              <CartDrawer />\n              <PrescriptionBasketDrawer />\n              <CareCheckoutReturn />\n              <CareSaveProgress />\n              <WelcomePopup />\n              <FeelingPopup />\n              {/* Financing discovery only — does not replace Tagada card checkout */}\n              <CherryFinancingWidget />\n            </div>\n          </CartProvider>\n        </PrescriptionBasketProvider>\n      </MemberProvider>\n    </CustomerAuthProvider>\n  );\n}\n\nexport default App;\n"},{"file":"src/components/Footer.tsx","before":"c94f986bdd77e284c1ce536c4a0a7b65992bc4e0e9865de8a1fda59c3951e509","next":"import { Link } from '@/router';\nimport { PHARMACY_FULFILLMENT_SHORT } from '@/data/pharmacyFulfillmentCopy';\nimport { Instagram, Mail } from 'lucide-react';\nimport { BrandLogo } from '@/components/BrandLogo';\n\nexport function Footer() {\n  return (\n    <footer className=\"bg-ink-900 text-cream-100\">\n      <div className=\"container-lux py-16\">\n        {/* Official logo — centered above footer content */}\n        <div className=\"flex justify-center mb-12 md:mb-16\">\n          <Link to=\"/\" className=\"inline-flex\" aria-label=\"My Bare Method home\">\n            <BrandLogo className=\"w-auto max-h-40 md:max-h-[200px] object-contain brightness-0 invert\" />\n          </Link>\n        </div>\n\n        <div className=\"grid gap-12 md:grid-cols-4\">\n          {/* Brand */}\n          <div className=\"md:col-span-1\">\n            <p className=\"text-sm text-cream-100/70 leading-relaxed mb-6\">\n              Luxury wellness, refined. Premium wellness products and provider-guided care — thoughtfully curated for your journey.\n            </p>\n            <div className=\"flex gap-4\">\n              <a href=\"#\" className=\"text-cream-100/70 hover:text-gold-300 transition-colors\" aria-label=\"Instagram\">\n                <Instagram size={20} />\n              </a>\n              <a href=\"mailto:info@thebaremethodmn.com\" className=\"text-cream-100/70 hover:text-gold-300 transition-colors\" aria-label=\"Email\">\n                <Mail size={20} />\n              </a>\n            </div>\n          </div>\n\n          {/* Shop */}\n          <div>\n            <p className=\"eyebrow text-gold-300 mb-4\">Shop</p>\n            <ul className=\"space-y-2.5 text-sm text-cream-100/70\">\n              <li><Link to=\"/shop-all\" className=\"hover:text-gold-300 transition-colors\">Shop All</Link></li>\n              <li><Link to=\"/alacarte\" className=\"hover:text-gold-300 transition-colors\">One-Time Purchases</Link></li>\n              <li><Link to=\"/section/accessories\" className=\"hover:text-gold-300 transition-colors\">Accessories</Link></li>\n              <li><Link to=\"/best-sellers\" className=\"hover:text-gold-300 transition-colors\">Best Sellers</Link></li>\n              <li><Link to=\"/section/weight-management\" className=\"hover:text-gold-300 transition-colors\">Weight Management</Link></li>\n              <li><Link to=\"/section/longevity-cognitive\" className=\"hover:text-gold-300 transition-colors\">Longevity &amp; Energy</Link></li>\n              <li><Link to=\"/section/womens-hormone-therapy\" className=\"hover:text-gold-300 transition-colors\">Hormone Support</Link></li>\n            </ul>\n          </div>\n\n          {/* Concerns */}\n          <div>\n            <p className=\"eyebrow text-gold-300 mb-4\">Shop by Concern</p>\n            <ul className=\"space-y-2.5 text-sm text-cream-100/70\">\n              <li><Link to=\"/concern/weight-management\" className=\"hover:text-gold-300 transition-colors\">Weight Management</Link></li>\n              <li><Link to=\"/concern/longevity-aging\" className=\"hover:text-gold-300 transition-colors\">Longevity & Aging</Link></li>\n              <li><Link to=\"/concern/hormone-balance\" className=\"hover:text-gold-300 transition-colors\">Hormone Balance</Link></li>\n              <li><Link to=\"/concern/energy-vitality\" className=\"hover:text-gold-300 transition-colors\">Energy & Vitality</Link></li>\n              <li><Link to=\"/concern/cognitive-support\" className=\"hover:text-gold-300 transition-colors\">Cognitive Support</Link></li>\n              <li><Link to=\"/concern/recovery-performance\" className=\"hover:text-gold-300 transition-colors\">Recovery & Performance</Link></li>\n              <li><Link to=\"/concern/sleep-stress\" className=\"hover:text-gold-300 transition-colors\">Sleep & Stress</Link></li>\n            </ul>\n          </div>\n\n          {/* Legal */}\n          <div>\n            <p className=\"eyebrow text-gold-300 mb-4\">Legal & Support</p>\n            <ul className=\"space-y-2.5 text-sm text-cream-100/70\">\n              <li><Link to=\"/sms-reminders\" className=\"hover:text-gold-300 transition-colors\">Reminder Preferences</Link></li>\n              <li><Link to=\"/privacy-policy\" className=\"hover:text-gold-300 transition-colors\">Privacy Policy</Link></li>\n              <li><Link to=\"/terms\" className=\"hover:text-gold-300 transition-colors\">Terms & Conditions</Link></li>\n              <li><Link to=\"/refund-policy\" className=\"hover:text-gold-300 transition-colors\">Refund & Replacement Policy</Link></li>\n              <li><Link to=\"/shipping-policy\" className=\"hover:text-gold-300 transition-colors\">Shipping Policy</Link></li>\n              <li><Link to=\"/subscription-terms\" className=\"hover:text-gold-300 transition-colors\">Subscription &amp; Cancellation Terms</Link></li>\n              <li><Link to=\"/accessibility\" className=\"hover:text-gold-300 transition-colors\">Accessibility Statement</Link></li>\n              <li><Link to=\"/consumer-data\" className=\"hover:text-gold-300 transition-colors\">Consumer Health Data Notice</Link></li>\n              <li><Link to=\"/medical-director\" className=\"hover:text-gold-300 transition-colors\">Meet Our Medical Director</Link></li>\n              <li><Link to=\"/contact\" className=\"hover:text-gold-300 transition-colors\">Contact Us</Link></li>\n              <li><Link to=\"/faq\" className=\"hover:text-gold-300 transition-colors\">FAQs</Link></li>\n            </ul>\n          </div>\n        </div>\n\n        {/* Disclosures */}\n        <div className=\"mt-12 border-t border-cream-100/10 pt-8\">\n          <p className=\"text-xs text-cream-100/50 leading-relaxed mb-4\">\n            These statements have not been evaluated by the Food and Drug Administration. Products are not intended to diagnose, treat, cure, or prevent any disease. Provider Care and prescription therapies require a medical intake and review by a licensed provider; fulfillment occurs only after provider approval and is not a guarantee of prescription. If a requested prescription therapy is not approved after payment, eligible paid amounts are refunded under our Refund &amp; Replacement Policy.\n          </p>\n          <p className=\"text-xs text-cream-100/50 leading-relaxed mb-4\">\n            Telemedicine and pharmacy fulfillment availability vary by service, product, provider licensure, pharmacy, laboratory, and state requirements. Medical Director: Dr. Jerry J. Cattelane Jr., D.O. {PHARMACY_FULFILLMENT_SHORT}\n          </p>\n          <div className=\"flex flex-col md:flex-row justify-between gap-4 text-xs text-cream-100/50\">\n            <p>© {new Date().getFullYear()} My Bare Method. All rights reserved. A brand of The Bare Method.</p>\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n"},{"file":"src/components/CareSaveProgress.tsx","before":null,"next":"import { useEffect, useRef, useState } from 'react';\nimport { CARE_CHECKOUT_REQUESTED, continueCareCheckoutWindow, validatedCareCheckoutUrl } from '@/lib/commerce/careCheckoutWindow';\nimport { CareProgressForm } from './CareProgressForm';\n\n/** Checkout interception stays gated until reminder enrollment is verified. */\nexport function CareSaveProgress() {\n  const dialog = useRef<HTMLDialogElement>(null);\n  const [url, setUrl] = useState('');\n  const [attempt, setAttempt] = useState(0);\n  useEffect(() => {\n    const requested = (event: Event) => {\n      const value = (event as CustomEvent<{ url: string }>).detail?.url;\n      try {\n        const destination = validatedCareCheckoutUrl(value);\n        if (!dialog.current) return;\n        event.preventDefault();\n        setUrl(destination); setAttempt(value => value + 1);\n        dialog.current.showModal();\n      } catch { /* Invalid checkout destinations are not captured. */ }\n    };\n    window.addEventListener(CARE_CHECKOUT_REQUESTED, requested);\n    return () => window.removeEventListener(CARE_CHECKOUT_REQUESTED, requested);\n  }, []);\n  return <dialog ref={dialog} aria-labelledby=\"care-save-title\" className=\"m-auto max-h-[90vh] w-[calc(100%-2rem)] max-w-lg overflow-y-auto rounded-3xl bg-cream-50 p-7 text-ink-900 shadow-2xl backdrop:bg-black/50\">\n    <h2 id=\"care-save-title\" className=\"font-serif text-2xl\">Save your progress</h2>\n    {url && <CareProgressForm key={attempt} checkoutUrl={url} onContinue={() => {\n      dialog.current?.close(); setUrl(''); continueCareCheckoutWindow(url);\n    }} />}\n    <button type=\"button\" className=\"mt-4 w-full text-sm\" onClick={() => { dialog.current?.close(); setUrl(''); }}>Back to shopping</button>\n  </dialog>;\n}\n"},{"file":"src/components/CareProgressForm.tsx","before":null,"next":"import { useRef, useState, type FormEvent } from 'react';\nimport { saveCareProgress } from '@/lib/commerce/careProgress';\n\n/** Shared consent capture. Saving preferences never enrolls a messaging workflow. */\nexport function CareProgressForm({ checkoutUrl, onContinue }: { checkoutUrl: string; onContinue: () => void }) {\n  const [name, setName] = useState('');\n  const [email, setEmail] = useState('');\n  const [phone, setPhone] = useState('');\n  const [emailConsent, setEmailConsent] = useState(false);\n  const [smsConsent, setSmsConsent] = useState(false);\n  const [busy, setBusy] = useState(false);\n  const [saved, setSaved] = useState(false);\n  const [error, setError] = useState('');\n  const requestId = useRef('');\n  const save = async (event: FormEvent) => {\n    event.preventDefault();\n    if (busy) return;\n    if (!emailConsent && !smsConsent) { onContinue(); return; }\n    requestId.current ||= crypto.randomUUID();\n    setBusy(true); setError('');\n    try {\n      await saveCareProgress({ name, email, phone, emailConsent, smsConsent }, checkoutUrl, requestId.current);\n      setSaved(true); setName(''); setEmail(''); setPhone('');\n    } catch (e) {\n      setError(e instanceof Error ? e.message : 'Please retry or continue without reminders.');\n    } finally { setBusy(false); }\n  };\n  if (saved) return <div role=\"status\" className=\"mt-4 space-y-4\">\n    <p>Your reminder preferences are saved. Reminder delivery is not active yet. Saving does not place an order or complete payment or intake.</p>\n    <button type=\"button\" className=\"btn-primary w-full\" onClick={onContinue}>Continue</button>\n  </div>;\n  return <form onSubmit={save} className=\"mt-4 space-y-4\">\n    <p className=\"text-sm leading-relaxed\">Choose whether My Bare Method may remind you about an unfinished cart, checkout, payment, or intake. You can continue shopping without signing up.</p>\n    <p className=\"rounded-lg bg-white p-3 text-sm\">Reminder delivery is not active yet. You can save your preferences now; no reminders will be sent until the service is available.</p>\n    <label className=\"block text-sm\">Name<input autoComplete=\"name\" required={emailConsent || smsConsent} maxLength={160} value={name} onChange={e => setName(e.target.value)} className=\"mt-1 block w-full rounded-lg border p-3\" /></label>\n    <label className=\"block text-sm\">Email<input type=\"email\" autoComplete=\"email\" required={emailConsent || smsConsent} maxLength={254} value={email} onChange={e => setEmail(e.target.value)} className=\"mt-1 block w-full rounded-lg border p-3\" /></label>\n    <label className=\"block text-sm\">Mobile phone (optional)<input type=\"tel\" autoComplete=\"tel\" required={smsConsent} placeholder=\"+16125550123\" maxLength={16} value={phone} onChange={e => setPhone(e.target.value)} className=\"mt-1 block w-full rounded-lg border p-3\" /><span className=\"mt-1 block text-xs\">Include your country code, for example +1 for the United States.</span></label>\n    <label className=\"flex items-start gap-3 text-sm\"><input type=\"checkbox\" checked={emailConsent} onChange={e => setEmailConsent(e.target.checked)} className=\"mt-1\" />I agree to receive email reminders from My Bare Method about my unfinished cart, checkout, payment, or intake.</label>\n    <label className=\"flex items-start gap-3 text-sm\"><input type=\"checkbox\" checked={smsConsent} onChange={e => setSmsConsent(e.target.checked)} className=\"mt-1\" />I agree to receive automated text reminders from My Bare Method at the number provided about my unfinished cart, checkout, payment, or intake. Up to 3 texts per unfinished step, at 15 minutes, 1 hour, and 24 hours. Message and data rates may apply. Reply STOP to opt out or HELP for help. Consent is not a condition of purchase.</label>\n    <p className=\"text-xs leading-relaxed text-ink-600\">Both choices are optional and start unchecked. Contact details and consent are used to manage your reminder preferences and delivery. Mobile information and SMS consent are not sold or shared with third parties or affiliates for their marketing. <a href=\"/privacy-policy\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"underline\">Privacy Policy</a> · <a href=\"/terms\" target=\"_blank\" rel=\"noopener noreferrer\" className=\"underline\">Terms &amp; Conditions</a>. For help, email <a href=\"mailto:info@thebaremethodmn.com\" className=\"underline\">info@thebaremethodmn.com</a>.</p>\n    {error && <p role=\"alert\" className=\"text-sm text-red-700\">{error}</p>}\n    <button disabled={busy} className=\"btn-primary w-full\" type=\"submit\">{busy ? 'Saving…' : emailConsent || smsConsent ? 'Save my preferences' : 'Continue without reminders'}</button>\n    {(emailConsent || smsConsent) && <button disabled={busy} type=\"button\" className=\"w-full text-sm underline\" onClick={onContinue}>Continue without reminders</button>}\n  </form>;\n}\n"},{"file":"src/pages/SmsRemindersPage.tsx","before":null,"next":"import { CareProgressForm } from '@/components/CareProgressForm';\nimport { navigate } from '@/router';\n\nexport function SmsRemindersPage() {\n  return <section className=\"bg-cream-50 px-4 pb-20 pt-32 text-ink-900\">\n    <div className=\"mx-auto max-w-xl rounded-3xl border border-ink-900/10 p-6 md:p-8\">\n      <p className=\"eyebrow mb-3\">My Bare Method</p>\n      <h1 className=\"font-serif text-3xl\">Save your progress</h1>\n      <CareProgressForm checkoutUrl=\"https://mybaremethod.com/sms-reminders\" onContinue={() => navigate('/shop-all')} />\n    </div>\n  </section>;\n}\n"},{"file":"src/pages/PrivacyPolicyPage.tsx","before":"44c6ecd7ad896db678a90d446d0af64d51f2baf963d2dd9f8eca4551c75307b1","next":"import { LegalPageLayout, LegalBulletList } from '@/components/LegalPageLayout';\n\nexport function PrivacyPolicyPage() {\n  return (\n    <LegalPageLayout\n      eyebrow=\"Privacy\"\n      title=\"Privacy Policy\"\n      intro=\"Your privacy matters to us. This policy explains what we collect, how we use it, and the rights you have over your data.\"\n      lastUpdated=\"September 22, 2026\"\n      sections={[\n        {\n          id: 'reminder-preferences',\n          title: 'Optional Email and Text Reminders',\n          body: <>\n            <p>When you save reminder preferences, we collect your name, email, optional mobile number, the choices you select, the consent version and timestamp, and the form or checkout reference. Email and SMS consent are separate and optional. We use these records to manage reminders about unfinished carts, checkout, payment, and intake. Saving preferences does not place an order or complete payment or intake.</p>\n            <p>Mobile information, text-message opt-in data, and SMS consent are not sold or shared with third parties or affiliates for marketing or promotional purposes. We may provide this information to service providers solely to operate and deliver the messages you requested. Clinical answers and payment credentials are not included in reminder messages.</p>\n            <p>Reply STOP to opt out of texts or HELP for help. You can also request withdrawal of reminder consent by emailing info@thebaremethodmn.com. Reminder delivery is not currently active; saving preferences does not start a message sequence.</p>\n          </>,\n        },\n        {\n          id: 'information-we-collect',\n          title: 'Information We Collect',\n          body: (\n            <>\n              <p>We collect the following categories of personal and health-related information:</p>\n              <LegalBulletList items={[\n                'Account information: name, email address, password (hashed), and phone number when you create an account.',\n                'Intake forms: medical history, current medications, symptoms, goals, and other health details submitted during provider-guided therapy intake.',\n                'Payment information: billing name and address, payment method type (for example, Credit / Debit Card via our secure hosted checkout), order references, and payment status. Payment card information is processed securely by our payment service providers. My Bare Method does not store full card numbers or security codes.',\n                'Shipping information: delivery name, address, and phone number provided at checkout.',\n                'Order history: products purchased, dates, quantities, and order status.',\n                'Usage data: pages visited, time on site, and interactions collected via cookies and analytics tools.',\n              ]} />\n            </>\n          ),\n        },\n        {\n          id: 'how-we-use-it',\n          title: 'How We Use Your Information',\n          body: (\n            <>\n              <p>We use the information we collect to:</p>\n              <LegalBulletList items={[\n                'Process and fulfill orders, including shipping and delivery.',\n                'Verify identity and prevent fraud.',\n                'Facilitate medical intake and provider review for therapy products.',\n                'Communicate with you about your orders, account, and customer service requests.',\n                'Send marketing emails only with your consent; you may opt out at any time.',\n                'Improve our website, products, and services through analytics.',\n                'Comply with legal, regulatory, and tax obligations.',\n              ]} />\n            </>\n          ),\n        },\n        {\n          id: 'storage-and-protection',\n          title: 'Data Storage and Protection',\n          body: (\n            <>\n              <p>\n                Your data is stored on secure servers with access restricted to authorized personnel who need it to\n                perform their duties. We use encryption in transit (TLS) and at rest. Customers complete public checkout\n                through a secure hosted card payment flow. Payment card information is processed securely by our payment\n                service providers. My Bare Method does not store full card numbers or security codes.\n              </p>\n              <p>\n                Despite our safeguards, no system is perfectly secure. In the event of a data breach affecting your\n                personal information, we will notify affected users in accordance with applicable U.S. state laws.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'hipaa',\n          title: 'HIPAA and Protected Health Information',\n          body: (\n            <>\n              <p>\n                Certain products require a medical intake and review by a licensed provider. The health information\n                you submit in intake forms may constitute Protected Health Information (PHI) under the Health Insurance\n                Portability and Accountability Act (HIPAA) and the HIPAA Privacy and Security Rules.\n              </p>\n              <p>\n                When HIPAA applies, PHI is handled in accordance with applicable HIPAA requirements. Access to PHI is\n                limited to the minimum necessary workforce members and contracted providers involved in your care. We do\n                not disclose PHI for marketing purposes without your written authorization when authorization is legally\n                required. You may request access to, or an accounting of disclosures of, your PHI by contacting us using\n                the information in the Contact section below.\n              </p>\n              <p>\n                If a provider determines that a requested therapy is not appropriate for you, your PHI is retained only\n                as long as necessary to document the review and then securely disposed of per our retention schedule.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'cookies-analytics',\n          title: 'Cookies and Analytics',\n          body: (\n            <>\n              <p>\n                We use cookies and similar technologies to keep you logged in, remember items in your cart, and\n                understand how visitors use our site. You can disable cookies in your browser settings, though some\n                features may not function properly without them.\n              </p>\n              <p>\n                We use third-party analytics tools that collect aggregated, de-identified usage data to help us improve\n                the website. These tools may use cookies but do not identify you personally.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'third-party-services',\n          title: 'Third-Party Services',\n          body: (\n            <>\n              <p>We share limited data with trusted third-party service providers to operate our business:</p>\n              <LegalBulletList items={[\n                'Payment processors: process card payments on our behalf under their own terms and privacy practices. We receive confirmation details needed to match payment to your order.',\n                'Shipping providers: receive your name, address, and phone number to deliver your order and provide tracking updates.',\n                'Form and intake platforms: securely store medical intake responses for provider review.',\n                'Email and SMS providers: receive your contact information to send transactional and, with consent, marketing messages.',\n              ]} />\n              <p>\n                We do not sell your personal information to third parties. Service providers are bound by contracts\n                requiring them to protect your data and use it only for the purposes we specify.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'us-privacy-rights',\n          title: 'Your Privacy Rights (U.S.)',\n          body: (\n            <>\n              <p>\n                Depending on your state of residence, you may have the following rights under U.S. privacy laws,\n                including the California Consumer Privacy Act (CCPA), the California Privacy Rights Act (CPRA), and\n                comparable state laws:\n              </p>\n              <LegalBulletList items={[\n                'Know what personal information we collect about you and how it is used.',\n                'Request access to or a copy of your personal information.',\n                'Request deletion of your personal information, subject to legal retention obligations.',\n                'Correct inaccurate personal information.',\n                'Opt out of the sale or sharing of personal information for cross-context behavioral advertising.',\n                'Limit the use of sensitive personal information.',\n                'Non-discrimination: we will not deny service or charge different prices for exercising your rights.',\n              ]} />\n              <p>\n                To exercise any of these rights, contact us using the information in the Contact section. We will verify\n                your identity before processing your request and respond within 45 days, as required by law.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'data-retention',\n          title: 'Data Retention',\n          body: (\n            <>\n              <p>\n                We retain personal information only as long as necessary to fulfill the purposes described in this\n                policy, comply with legal obligations, resolve disputes, and enforce our agreements. Medical intake\n                data is retained per applicable healthcare record retention requirements. Order and tax records are\n                retained for the period required by law.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'children',\n          title: \"Children's Privacy\",\n          body: (\n            <>\n              <p>\n                Our services are not intended for individuals under 18. We do not knowingly collect personal\n                information from children. If you believe a child has provided us information, contact us and we will\n                delete it.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'changes',\n          title: 'Changes to This Policy',\n          body: (\n            <>\n              <p>\n                We may update this Privacy Policy from time to time. The \"Last updated\" date at the top reflects the\n                most recent revision. Material changes will be posted on this page and, where appropriate, communicated\n                by email.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'contact',\n          title: 'Contact Us',\n          body: (\n            <>\n              <p>If you have questions about this Privacy Policy or wish to exercise your privacy rights, contact us:</p>\n              <p>\n                My Bare Method<br />\n                Email: info@thebaremethodmn.com<br />\n                Phone: (218) 656-7189<br />\n                Mailing Address: 15115 Cedar Ave Suite 33, Apple Valley, MN 55124\n              </p>\n            </>\n          ),\n        },\n      ]}\n    />\n  );\n}\n"},{"file":"src/pages/TermsPage.tsx","before":"cafc202e3f3dc8a897d7bd5f58cccb0fe14cf1f1c43beba4556cc7f9d86bf83f","next":"import { LegalPageLayout, LegalBulletList } from '@/components/LegalPageLayout';\n\nexport function TermsPage() {\n  return (\n    <LegalPageLayout\n      eyebrow=\"Terms\"\n      title=\"Terms & Conditions\"\n      intro=\"These terms govern your use of our website and products. Please read them carefully before placing an order.\"\n      lastUpdated=\"September 22, 2026\"\n      sections={[\n        {\n          id: 'reminder-program',\n          title: 'My Bare Method Reminder Program',\n          body: <>\n            <p>You may separately opt in to automated text reminders about unfinished carts, checkout, payment, or intake through our Save your progress form. Consent is optional, is not a condition of purchase, and does not authorize promotional campaigns unrelated to these reminders.</p>\n            <p>When available, the program may send up to 3 texts per unfinished step, at 15 minutes, 1 hour, and 24 hours. Reminders for a step stop after completion is confirmed. Message and data rates may apply. Reply STOP to unsubscribe or HELP for help, or email info@thebaremethodmn.com. Carriers are not liable for delayed or undelivered messages.</p>\n            <p>Reminder delivery is not active yet. Saving preferences records your choices only; it does not place an order, collect payment, complete intake, or start reminders. Please finish any required steps directly rather than relying on a reminder.</p>\n            <p>See our <a href=\"/privacy-policy\" className=\"underline\">Privacy Policy</a> for how we handle mobile information and consent.</p>\n          </>,\n        },\n        {\n          id: 'agreement',\n          title: 'Agreement to Terms',\n          body: (\n            <>\n              <p>\n                By accessing or using the My Bare Method website (the \"Site\") and purchasing our products, you agree to\n                be bound by these Terms & Conditions and our Privacy Policy and Refund & Replacement Policy. If you do\n                not agree, do not use the Site or purchase our products.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'website-use',\n          title: 'Website Use',\n          body: (\n            <>\n              <p>\n                You may use this Site for lawful purposes only. You agree not to misuse, disrupt, or attempt to gain\n                unauthorized access to the Site, its systems, or data. We may modify or discontinue any part of the Site\n                at any time without notice.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'eligibility',\n          title: 'Eligibility',\n          body: (\n            <>\n              <p>\n                You must be at least 18 years of age and legally able to enter into contracts to use this Site and\n                purchase products. By placing an order, you represent and warrant that you meet these requirements.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'accounts',\n          title: 'Accounts',\n          body: (\n            <>\n              <p>\n                When you create an account, you agree to provide accurate and complete information and to keep your\n                password confidential. You are responsible for all activity under your account. Notify us immediately of\n                any unauthorized use.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'pricing',\n          title: 'Pricing and Availability',\n          body: (\n            <>\n              <p>\n                All prices are listed in U.S. dollars and are subject to change without notice. We strive for accuracy\n                but may occasionally display incorrect pricing. In the event of a pricing error, we may cancel your\n                order and, if payment has already been received and verified, issue a refund of applicable paid amounts.\n                Some products, including Provider Care therapies, have variable pricing determined after medical intake\n                and provider review.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'payment',\n          title: 'Payment Terms',\n          body: (\n            <>\n              <p>\n                Public checkout is completed by Credit / Debit Card through our secure hosted card checkout. Your order\n                remains unpaid until card payment is confirmed.\n              </p>\n              <LegalBulletList items={[\n                'Order submission alone does not constitute payment.',\n                'Processing and fulfillment do not begin solely because checkout was submitted. Processing begins after payment has been received and, where applicable, required provider review has been completed.',\n                'Applicable taxes are included in displayed prices where required.',\n                'Purchase and payment do not guarantee prescription or treatment approval.',\n              ]} />\n            </>\n          ),\n        },\n        {\n          id: 'subscriptions',\n          title: 'Subscriptions and Recurring Periods',\n          body: (\n            <>\n              <p>\n                Eligible prescription products may be available through Subscribe &amp; Save. Subscriptions are billed\n                monthly to your card while active. The recurring amount and any applicable fulfillment details are\n                shown before enrollment whenever reasonably possible.\n              </p>\n              <LegalBulletList items={[\n                'You may submit a cancellation request from your account or by contacting support. Requests do not reverse a payment already received or stop an order already in provider, pharmacy, or fulfillment processing.',\n                'We may change the underlying retail price with notice when required; the Subscribe & Save discount remains 15% unless the terms are amended.',\n                'Failed or past-due payments may pause fulfillment until payment is resolved.',\n              ]} />\n            </>\n          ),\n        },\n        {\n          id: 'subscription-pricing',\n          title: 'Subscribe & Save Pricing',\n          body: (\n            <>\n              <p>\n                Eligible prescription subscriptions receive 15% off the authoritative one-time medication price.\n                Provider visits, labs, services, and accessories are separate one-time purchases unless a specific\n                offer says otherwise.\n              </p>\n              <p>\n                Subscriptions continue month-to-month until a valid cancellation becomes effective. Medication\n                fulfillment remains subject to provider approval and pharmacy availability.\n              </p>\n              <p>\n                The underlying medication price may change with notice as permitted by law and these terms.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'shipping',\n          title: 'Shipping and Order Processing',\n          body: (\n            <>\n              <p>\n                Processing and shipping timelines begin only after payment has been received and any required provider\n                review/approval has been completed. Accessories are the only storefront items with a separate $10\n                shipping charge. Prescription, provider, and laboratory workflows may use GEN Health or a dispensing\n                partner checkout path where applicable. Carrier transit times vary by destination; delivery dates are\n                not guaranteed. We are not liable for carrier delays beyond our control.\n              </p>\n              <p>\n                Provider Care and therapy products require medical intake and provider approval before fulfillment.\n                Fulfillment occurs only after applicable requirements are satisfied. If a provider does not approve the\n                therapy after payment has been received, eligible paid amounts for the unapproved product are refunded\n                in accordance with our Refund Policy.\n              </p>\n              <p>\n                For applicable Women’s Hormone Therapy orders, updated labs may be required before a provider can make\n                treatment decisions. When labs are required, customers choose from the current lab options and add the\n                selected lab before continuing. Lab ordering, intake, payment, and results are handled through the\n                secure clinical lab workflow.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'promotions',\n          title: 'Promotional Codes',\n          body: (\n            <>\n              <p>\n                When offered, FIRSTTIME provides $25 off an eligible first order and OGTBM provides 25% off eligible\n                products. Enter one code at GEN Health checkout and select Apply before paying. GEN Health confirms\n                product eligibility, usage limits, and the final discount. FIRSTTIME is limited to one use per patient\n                with no prior paid order; eligibility uses the checkout email. GEN codes do not apply to the separate\n                accessories checkout. An initial-purchase discount does not change recurring renewal prices unless\n                the offer explicitly says so.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'intellectual-property',\n          title: 'Intellectual Property',\n          body: (\n            <>\n              <p>\n                All content on this Site, including text, graphics, logos, product names, and design, is the property\n                of My Bare Method or its licensors and is protected by U.S. and international intellectual property\n                laws. You may not copy, reproduce, distribute, or create derivative works without our written\n                permission.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'prohibited-use',\n          title: 'Prohibited Use',\n          body: (\n            <>\n              <p>You agree not to:</p>\n              <LegalBulletList items={[\n                'Use the Site for any unlawful purpose or in violation of these Terms.',\n                'Resell, redistribute, or mislabel our products.',\n                'Use provider-directed or prescription products without required licensed-provider review, or contrary to applicable law and labeling.',\n                'Attempt to reverse engineer, decompile, or otherwise extract source code or proprietary data.',\n                'Interfere with the Site\\'s security, operation, or functionality.',\n                'Scrape, harvest, or collect user data without authorization.',\n              ]} />\n            </>\n          ),\n        },\n        {\n          id: 'limitation-of-liability',\n          title: 'Limitation of Liability',\n          body: (\n            <>\n              <p>\n                To the maximum extent permitted by law, My Bare Method and its affiliates, officers, employees, and\n                providers shall not be liable for any indirect, incidental, special, consequential, or punitive\n                damages, or any loss of profits or revenues, arising from your use of the Site or products.\n              </p>\n              <p>\n                Our total liability for any claim arising from your use of the Site or purchase of products shall not\n                exceed the amount you paid us in the preceding 12 months. Some states do not allow certain liability\n                limitations, so these limits may not fully apply to you.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'governing-law',\n          title: 'Governing Law',\n          body: (\n            <>\n              <p>\n                These Terms are governed by the laws of the State of Texas, without regard to its conflict of laws\n                principles. You agree to the exclusive jurisdiction of the state and federal courts located in Travis\n                County, Texas, for any dispute arising from these Terms or your use of the Site.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'dispute-resolution',\n          title: 'Dispute Resolution',\n          body: (\n            <>\n              <p>\n                Any dispute, claim, or controversy arising out of these Terms or your use of the Site shall first be\n                addressed through good-faith negotiation. If unresolved within 30 days, the dispute shall be resolved\n                through binding arbitration administered by the American Arbitration Association in Austin, Texas,\n                under its Consumer Arbitration Rules.\n              </p>\n              <p>\n                You and My Bare Method waive any right to participate in a class action or class-wide arbitration. A\n                party may seek injunctive relief in court only to protect intellectual property rights.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'changes',\n          title: 'Changes to These Terms',\n          body: (\n            <>\n              <p>\n                We may update these Terms from time to time. The \"Last updated\" date reflects the most recent revision.\n                Your continued use of the Site after changes constitutes acceptance of the updated Terms.\n              </p>\n            </>\n          ),\n        },\n        {\n          id: 'contact',\n          title: 'Contact Us',\n          body: (\n            <>\n              <p>If you have questions about these Terms, contact us:</p>\n              <p>\n                My Bare Method<br />\n                Email: info@thebaremethodmn.com<br />\n                Phone: (218) 656-7189<br />\n                Mailing Address: 15115 Cedar Ave Suite 33, Apple Valley, MN 55124\n              </p>\n            </>\n          ),\n        },\n      ]}\n    />\n  );\n}\n"},{"file":"src/lib/commerce/careProgress.ts","before":null,"next":"export type CareProgressInput = {\n  name: string; email: string; phone: string;\n  emailConsent: boolean; smsConsent: boolean;\n};\n\nexport function validateCareProgress(input: CareProgressInput): string | null {\n  if (!input.name.trim() || input.name.trim().length > 160) return 'Enter your name.';\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(input.email.trim()) || input.email.length > 254) return 'Enter a valid email address.';\n  if (!input.emailConsent && !input.smsConsent) return 'Choose email or text reminders, or continue without reminders.';\n  if (input.smsConsent && !/^\\+[1-9]\\d{7,14}$/.test(input.phone.trim())) return 'Enter your phone with country code, such as +16125550123.';\n  return null;\n}\n\nexport async function saveCareProgress(input: CareProgressInput, checkoutUrl: string, requestId: string): Promise<void> {\n  const error = validateCareProgress(input);\n  if (error) throw new Error(error);\n  const base = import.meta.env.VITE_SUPABASE_URL;\n  const key = import.meta.env.VITE_SUPABASE_ANON_KEY;\n  if (!base || !key) throw new Error('We could not save your progress. Please retry or continue without reminders.');\n  // The server must persist consent and the attempt before returning accepted:true.\n  // Never enroll a reminder based on a button click or an optimistic browser flag.\n  const res = await fetch(`${base}/functions/v1/care-progress-save`, {\n    method: 'POST', headers: { 'Content-Type': 'application/json', apikey: key, Authorization: `Bearer ${key}` },\n    body: JSON.stringify({ name: input.name.trim(), email: input.email.trim(),\n      phone: input.smsConsent ? input.phone.trim() : null,\n      emailConsent: input.emailConsent, smsConsent: input.smsConsent,\n      consentVersion: 'care-progress-2026-09-22', checkoutUrl, requestId }),\n    signal: AbortSignal.timeout(12000),\n  });\n  const result = await res.json().catch(() => null);\n  if (!res.ok || result?.accepted !== true) throw new Error('We could not save your progress. Please retry or continue without reminders.');\n}\n"},{"file":"src/lib/commerce/careCheckoutWindow.ts","before":"ecc10b11dc85fdbdbdeb7eccb479eaea422a1b138cd83d06179cbad2277d679b","next":"export const CARE_CHECKOUT_OPENED = 'mbm:care-checkout-opened';\nexport const CARE_CHECKOUT_REQUESTED = 'mbm:care-checkout-requested';\n\nexport function validatedCareCheckoutUrl(value: string): string {\n  const url = new URL(value);\n  if (url.origin !== 'https://app.genhealthehr.com' || url.username || url.password ||\n      !/^\\/f5e0mdyBYnDh7HGvek0C\\/product\\/[^/]+$/.test(url.pathname)) {\n    throw new Error('GEN_CHECKOUT_URL_NOT_ALLOWED');\n  }\n  return url.toString();\n}\n\n/** Opens only on a user gesture. A closed/blocked window never means completed care. */\nexport function openCareCheckoutWindow(value: string): void {\n  const url = validatedCareCheckoutUrl(value);\n  if (import.meta.env.VITE_CARE_PROGRESS_ENABLED === 'true') {\n    const request = new CustomEvent(CARE_CHECKOUT_REQUESTED, { cancelable: true, detail: { url } });\n    if (!window.dispatchEvent(request)) return;\n  }\n  continueCareCheckoutWindow(url);\n}\n\n/** Explicit continuation after the optional progress form; never opens twice. */\nexport function continueCareCheckoutWindow(value: string): void {\n  const url = validatedCareCheckoutUrl(value);\n  try {\n    window.open(url, '_blank', 'popup,width=620,height=820,noopener,noreferrer');\n  } catch {\n    // Some embedded browsers disallow popups; the return dialog provides a normal link.\n  } finally {\n    // noopener may return null even on success; offer an explicit fallback, not a second popup.\n    window.dispatchEvent(new CustomEvent(CARE_CHECKOUT_OPENED, { detail: { url } }));\n  }\n}\n"},{"file":"scripts/prerender.tsx","before":"46a43d9604d28a1f3665f4544da979bc283695cbb6ec882681ed99698d64b81c","next":"import { renderToString } from 'react-dom/server';\nimport { createElement } from 'react';\nimport { writeFileSync, readFileSync, mkdirSync, existsSync } from 'node:fs';\nimport { join, dirname } from 'node:path';\n\nimport { CartProvider } from '@/context/CartContext';\nimport { PrescriptionBasketProvider } from '@/context/PrescriptionBasketContext';\nimport { MemberProvider } from '@/context/MemberContext';\nimport { CustomerAuthProvider } from '@/context/CustomerAuthContext';\nimport { Header } from '@/components/Header';\nimport { Footer } from '@/components/Footer';\nimport { CartDrawer } from '@/components/CartDrawer';\nimport { PrescriptionBasketDrawer } from '@/components/PrescriptionBasketDrawer';\nimport { HomePage } from '@/pages/HomePage';\nimport { GoalsPage } from '@/pages/GoalsPage';\nimport { ShopAllPage } from '@/pages/ShopAllPage';\nimport { BestSellersPage } from '@/pages/BestSellersPage';\nimport { SubscriptionsPage } from '@/pages/SubscriptionsPage';\nimport { AlaCartePage } from '@/pages/AlaCartePage';\nimport { AboutPage } from '@/pages/AboutPage';\nimport { MedicalDirectorPage } from '@/pages/MedicalDirectorPage';\nimport { FaqPage } from '@/pages/FaqPage';\nimport { ContactPage } from '@/pages/ContactPage';\nimport { SuccessPage } from '@/pages/SuccessPage';\nimport { CancelPage } from '@/pages/CancelPage';\nimport { SectionPage } from '@/pages/SectionPage';\nimport { ConcernPage } from '@/pages/ConcernPage';\nimport { ProductPage } from '@/pages/ProductPage';\nimport { RefundPolicyPage } from '@/pages/RefundPolicyPage';\nimport { ShippingPolicyPage } from '@/pages/ShippingPolicyPage';\nimport { SubscriptionTermsPage } from '@/pages/SubscriptionTermsPage';\nimport { AccessibilityPage } from '@/pages/AccessibilityPage';\nimport { ConsumerDataPage } from '@/pages/ConsumerDataPage';\nimport { PrivacyPolicyPage } from '@/pages/PrivacyPolicyPage';\nimport { TermsPage } from '@/pages/TermsPage';\nimport { SmsRemindersPage } from '@/pages/SmsRemindersPage';\nimport { LabDetailPage, OrderLabsPage } from '@/pages/OrderLabsPage';\nimport { labOptions } from '@/data/labs';\nimport { visibleProducts as products, sections, concerns, goals, type Product } from '@/data/products';\n\nconst BASE_URL = 'https://mybaremethod.com';\n\nfunction renderPage(component: React.ReactElement) {\n  return renderToString(\n    createElement(CustomerAuthProvider, null,\n      createElement(MemberProvider, null,\n        createElement(PrescriptionBasketProvider, null,\n          createElement(CartProvider, null,\n            createElement('div', { className: 'min-h-screen bg-cream-50' },\n              createElement(Header),\n              createElement('main', null, component),\n              createElement(Footer),\n              createElement(CartDrawer),\n              createElement(PrescriptionBasketDrawer),\n            ),\n          ),\n        ),\n      ),\n    ),\n  );\n}\n\nfunction buildProductJsonLd(product: Product) {\n  const data = {\n    '@context': 'https://schema.org',\n    '@type': 'Product',\n    name: product.displayName,\n    description: product.shortDescription,\n    image: `${BASE_URL}${product.image}`,\n    sku: product.id,\n    brand: { '@type': 'Brand', name: 'My Bare Method' },\n    offers: {\n      '@type': 'Offer',\n      price: product.startingPrice,\n      priceCurrency: 'USD',\n      availability: 'https://schema.org/InStock',\n      url: `${BASE_URL}/product/${product.slug}`,\n    },\n  };\n  return `<script type=\"application/ld+json\">${JSON.stringify(data)}</script>`;\n}\n\nfunction buildRoutes() {\n  const routes: { path: string; component: React.ReactElement; title: string; description: string; jsonLd?: string }[] = [\n    {\n      path: '/',\n      component: createElement(HomePage),\n      title: 'My Bare Method — Wellness, Elevated. Beautifully Personalized.',\n      description: 'Premium wellness products and provider-guided care with optional Subscribe & Save pricing on eligible prescriptions.',\n    },\n    {\n      path: '/shop-all',\n      component: createElement(ShopAllPage),\n      title: 'Shop All — My Bare Method',\n      description: 'Browse our complete catalog of prescription wellness products, provider care, and accessories.',\n    },\n    {\n      path: '/best-sellers',\n      component: createElement(BestSellersPage),\n      title: 'Best Sellers — My Bare Method',\n      description: 'Our most loved wellness products, curated by thousands of happy customers.',\n    },\n    {\n      path: '/subscriptions',\n      component: createElement(SubscriptionsPage),\n      title: 'Subscribe & Save — My Bare Method',\n      description: 'Save 15% on eligible monthly prescription renewals. Selected Two-Day or Next-Day shipping recurs with every renewal. Provider review required.',\n    },\n    {\n      path: '/alacarte',\n      component: createElement(AlaCartePage),\n      title: 'À La Carte — My Bare Method',\n      description: 'Purchase wellness products on your terms with no commitment required.',\n    },\n    {\n      path: '/about',\n      component: createElement(AboutPage),\n      title: 'About — My Bare Method',\n      description: 'Learn about My Bare Method — premium wellness products and provider-guided care.',\n    },\n    {\n      path: '/medical-director',\n      component: createElement(MedicalDirectorPage),\n      title: 'Meet Our Medical Director | My Bare Method',\n      description:\n        'Meet Dr. Jerry J. Cattelane Jr., D.O., Medical Director for My Bare Method, and learn about the clinical leadership supporting our provider-directed wellness programs.',\n    },\n    {\n      path: '/faq',\n      component: createElement(FaqPage),\n      title: 'FAQs — My Bare Method',\n      description: 'Frequently asked questions about My Bare Method products, memberships, and shipping.',\n    },\n    {\n      path: '/contact',\n      component: createElement(ContactPage),\n      title: 'Contact Us — My Bare Method',\n      description: 'Get in touch with the My Bare Method team for questions about your order or wellness journey.',\n    },\n    {\n      path: '/success',\n      component: createElement(SuccessPage),\n      title: 'Order Confirmed — My Bare Method',\n      description: 'Your payment was successful. Thank you for your order.',\n    },\n    {\n      path: '/cancel',\n      component: createElement(CancelPage),\n      title: 'Checkout Cancelled — My Bare Method',\n      description: 'Your payment was not completed. No charge has been made.',\n    },\n    {\n      path: '/goals',\n      component: createElement(GoalsPage),\n      title: 'Shop by Goal — My Bare Method',\n      description: 'Browse wellness products by your health and wellness goals.',\n    },\n    {\n      path: '/order-labs',\n      component: createElement(OrderLabsPage),\n      title: 'Order Labs — My Bare Method',\n      description: 'Choose in-home and walk-in lab options for provider-guided care.',\n    },\n    {\n      path: '/refund-policy',\n      component: createElement(RefundPolicyPage),\n      title: 'Refund & Replacement Policy — My Bare Method',\n      description: 'Read our refund and replacement policy for all products and memberships.',\n    },\n    {\n      path: '/shipping-policy',\n      component: createElement(ShippingPolicyPage),\n      title: 'Shipping Policy — My Bare Method',\n      description: 'Learn about our shipping methods, timelines, and discreet packaging.',\n    },\n    {\n      path: '/membership-terms',\n      component: createElement(SubscriptionTermsPage),\n      title: 'Subscription & Cancellation Terms — My Bare Method',\n      description: 'Recurring billing, shipping, and cancellation terms for My Bare Method prescription subscriptions.',\n    },\n    {\n      path: '/accessibility',\n      component: createElement(AccessibilityPage),\n      title: 'Accessibility Statement — My Bare Method',\n      description: 'Our commitment to accessibility for all users.',\n    },\n    {\n      path: '/consumer-data',\n      component: createElement(ConsumerDataPage),\n      title: 'Consumer Health Data Notice — My Bare Method',\n      description: 'How we handle and protect your consumer health data.',\n    },\n    {\n      path: '/privacy-policy',\n      component: createElement(PrivacyPolicyPage),\n      title: 'Privacy Policy — My Bare Method',\n      description: 'How My Bare Method collects, uses, and protects your personal information.',\n    },\n    {\n      path: '/sms-reminders',\n      component: createElement(SmsRemindersPage),\n      title: 'Reminder Preferences — My Bare Method',\n      description: 'Choose optional My Bare Method email and text reminders.',\n    },\n    {\n      path: '/terms',\n      component: createElement(TermsPage),\n      title: 'Terms & Conditions — My Bare Method',\n      description: 'Terms and conditions for using My Bare Method.',\n    },\n  ];\n\n  for (const s of sections) {\n    routes.push({\n      path: `/section/${s.id}`,\n      component: createElement(SectionPage, { sectionId: s.id, subFilter: undefined }),\n      title: `${s.label} — My Bare Method`,\n      description: s.description,\n    });\n  }\n\n  for (const c of concerns) {\n    routes.push({\n      path: `/concern/${c.id}`,\n      component: createElement(ConcernPage, { concernId: c.id }),\n      title: `${c.label} — My Bare Method`,\n      description: c.description,\n    });\n  }\n\n  for (const g of goals) {\n    routes.push({\n      path: `/goal/${g.id}`,\n      component: createElement(GoalsPage),\n      title: `${g.label} — My Bare Method`,\n      description: g.description,\n    });\n  }\n\n  for (const p of products) {\n    routes.push({\n      path: `/product/${p.slug}`,\n      component: createElement(ProductPage, { slug: p.slug }),\n      title: `${p.displayName} — My Bare Method`,\n      description: p.shortDescription,\n      jsonLd: buildProductJsonLd(p),\n    });\n  }\n\n  const labSlugs = new Set(\n    labOptions.map(lab =>\n      lab.displayName\n        .toLowerCase()\n        .replace(/&/g, 'and')\n        .replace(/[^a-z0-9]+/g, '-')\n        .replace(/^-|-$/g, ''),\n    ),\n  );\n\n  for (const slug of labSlugs) {\n    routes.push({\n      path: `/order-labs/${slug}`,\n      component: createElement(LabDetailPage, { slug }),\n      title: 'Lab Options — My Bare Method',\n      description: 'Select your collection style and lab network before ordering labs.',\n    });\n  }\n\n  return routes;\n}\n\nfunction main() {\n  const outDir = join(process.cwd(), 'dist');\n  const templatePath = join(outDir, 'index.html');\n  const template = readFileSync(templatePath, 'utf-8');\n  const routes = buildRoutes();\n\n  console.log(`Prerendering ${routes.length} routes...`);\n\n  for (const route of routes) {\n    try {\n      const innerHtml = renderPage(route.component);\n      const canonical = `${BASE_URL}${route.path === '/' ? '/' : route.path}`;\n      const ogUrl = canonical;\n\n      let html = template\n        .replace(/<title>.*?<\\/title>/, `<title>${route.title}</title>`)\n        .replace(/<meta name=\"description\" content=\"[^\"]*\"/, `<meta name=\"description\" content=\"${route.description}\"`)\n        .replace(/<link rel=\"canonical\" href=\"[^\"]*\"/, `<link rel=\"canonical\" href=\"${canonical}\"`)\n        .replace(/<meta property=\"og:title\" content=\"[^\"]*\"/, `<meta property=\"og:title\" content=\"${route.title}\"`)\n        .replace(/<meta property=\"og:description\" content=\"[^\"]*\"/, `<meta property=\"og:description\" content=\"${route.description}\"`)\n        .replace(/<meta property=\"og:url\" content=\"[^\"]*\"/, `<meta property=\"og:url\" content=\"${ogUrl}\"`);\n\n      if (route.jsonLd) {\n        html = html.replace('</head>', `${route.jsonLd}\\n</head>`);\n      }\n\n      html = html.replace(\n        '<div id=\"root\"></div>',\n        `<div id=\"root\">${innerHtml}</div>`\n      );\n\n      const filePath = route.path === '/' ? templatePath : join(outDir, route.path, 'index.html');\n      const dir = dirname(filePath);\n      if (!existsSync(dir)) mkdirSync(dir, { recursive: true });\n      writeFileSync(filePath, html);\n      console.log(`  prerendered: ${route.path}`);\n    } catch (err) {\n      console.error(`  ERROR prerendering ${route.path}:`, err instanceof Error ? err.message : err);\n    }\n  }\n\n  // Generate sitemap.xml (never include private /account/* portal routes)\n  let sitemap = '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\\n';\n  sitemap += '<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\\n';\n  for (const route of routes) {\n    if (route.path === '/account' || route.path.startsWith('/account/')) continue;\n    const priority = route.path === '/' ? '1.0'\n      : route.path.startsWith('/product/') ? '0.8'\n      : (route.path.startsWith('/section/') || route.path.startsWith('/concern/') || route.path.startsWith('/goal/')) ? '0.7'\n      : route.path.match(/\\/(privacy|terms|refund|shipping|membership-terms|accessibility|consumer-data)/) ? '0.3'\n      : '0.6';\n    sitemap += `  <url><loc>${BASE_URL}${route.path}</loc><changefreq>weekly</changefreq><priority>${priority}</priority></url>\\n`;\n  }\n  sitemap += '</urlset>\\n';\n  writeFileSync(join(outDir, 'sitemap.xml'), sitemap);\n  console.log(`  generated: sitemap.xml (${routes.length} URLs)`);\n\n  console.log('Prerendering complete.');\n}\n\nmain();\n"}];
